#!/usr/bin/env node
// Warns (non-blocking) when editing a GENERATED file directly — such edits are wiped on the next regeneration.
// A generated artifact carries a banner like:  <!-- GENERATED BY build_viewer3.py — edit <source>, not this file -->
// (or a # / // variant). If the target file's first ~40 lines contain that banner, remind the editor to change
// the generator/shell source instead. Non-blocking: it advises via systemMessage, never stops the edit —
// sometimes a throwaway tweak to generated output is intentional.
const fs = require('fs');
const chunks = [];
process.stdin.on('data', d => chunks.push(d));
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(Buffer.concat(chunks).toString());
    const tool = input.tool_name || '';
    if (tool !== 'Write' && tool !== 'Edit') return;
    const p = (input.tool_input || {}).file_path || '';
    if (!p || !fs.existsSync(p)) return;                 // new file: nothing generated to protect
    // read only the head — the banner lives at the top
    let head = '';
    try {
      const fd = fs.openSync(p, 'r');
      const buf = Buffer.alloc(4096);
      const n = fs.readSync(fd, buf, 0, 4096, 0);
      fs.closeSync(fd);
      head = buf.toString('utf8', 0, n);
    } catch (_) { return; }
    // match the banner: capture the generator name, and (optionally) the "edit <source>" the banner names.
    const line = (head.match(/GENERATED BY[^\n\r]*/i) || [''])[0];
    if (!line) return;
    const gen = ((line.match(/GENERATED BY\s+([^\s,;—–]+)/i) || [])[1] || 'the generator').trim();
    const src = ((line.match(/edit\s+([^\s,;]+(?:\.\w+)?)/i) || [])[1] || '').trim();
    const advice = src
      ? `Edit "${src}" (the source), then regenerate — direct edits to this file are overwritten by ${gen}.`
      : `This file is generated by ${gen}. Edit the generator/shell source and regenerate — direct edits here are overwritten on the next build.`;
    // non-blocking advisory: allow the edit, surface the warning
    process.stdout.write(JSON.stringify({
      continue: true,
      systemMessage: `⚠ "${p}" is a GENERATED artifact. ${advice}`,
    }));
  } catch (_) {}
});
